// Backfill EMBED: page POST /admin/embed on the live Worker until
// every listed record's embedding is fresh. The admin token is read
// in-process from /tmp/talents-admin-token (the P5 pattern — the
// token is generated by cf/scripts/set_discovery_secrets.py, kept
// only in that 0600 tmp file, never printed, never filed in the
// repo).
//
// The route is PAGED (limit + cursor, one bounded page per call);
// this driver threads the cursor page to page until the route
// reports done, then sweeps again from the start for stragglers
// (records a concurrent ingest may have added behind the cursor)
// until a full sweep embeds nothing.
//
// Checkpoint = embedding_meta in D1: a failed page is retried with
// backoff (D1 refuses work while a wrangler --file import is
// processing; the proxy also drops long calls occasionally) and is
// never skipped — the cursor only advances on an HTTP 200 page.
// After repeated failures on one page the page size halves (floor
// 25): a page that is merely heavy must not look identical to a
// page that is blocked. Restart-safe and idempotent throughout.
//
// Usage: node scripts/backfill-embed.mjs [--limit N] [--max-pages N] [--max-sweeps N]
import { readFileSync } from "node:fs";

const args = process.argv.slice(2);
const argNum = (name, dflt) => (args.includes(name) ? Number(args[args.indexOf(name) + 1]) : dflt);
const maxPages = argNum("--max-pages", 600);
const maxSweeps = argNum("--max-sweeps", 4);
let pageSize = argNum("--limit", 200);
const token = readFileSync("/tmp/talents-admin-token", "utf8").trim();

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function callPage(cursor) {
  let failures = 0;
  for (;;) {
    let status = 0, body = {};
    try {
      const res = await fetch("https://talents.sh/admin/embed", {
        method: "POST",
        headers: { "content-type": "application/json", "x-talents-admin": token },
        body: JSON.stringify({ limit: pageSize, cursor }),
        signal: AbortSignal.timeout(120_000),
      });
      status = res.status;
      body = await res.json().catch(() => ({}));
    } catch (e) {
      body = { error: `network: ${e.message}` };
    }
    if (status === 200) return { body, retries: failures };
    failures++;
    if (failures % 6 === 0 && pageSize > 25) {
      pageSize = Math.max(25, Math.floor(pageSize / 2));
      console.log(`page at cursor=${cursor}: ${failures} failures — halving page size to ${pageSize}`);
    }
    const wait = Math.min(30_000, 5_000 * failures);
    console.log(`page at cursor=${cursor}: HTTP ${status} ${JSON.stringify(body).slice(0, 120)} — retry ${failures} in ${wait / 1000}s`);
    if (failures >= 40) return { body: null, retries: failures };
    await sleep(wait);
  }
}

let cursor = null;
let pages = 0, totalEmbedded = 0, totalConsidered = 0, totalRetries = 0, sweeps = 0, sweepEmbedded = 0;
let gaveUp = false;
while (pages < maxPages && sweeps < maxSweeps) {
  const { body, retries } = await callPage(cursor);
  totalRetries += retries;
  if (!body) { gaveUp = true; break; }
  pages++;
  totalEmbedded += body.embedded ?? 0;
  totalConsidered += body.considered ?? 0;
  sweepEmbedded += body.embedded ?? 0;
  console.log(`sweep ${sweeps + 1} page ${pages}: considered=${body.considered} embedded=${body.embedded} skippedFresh=${body.skippedFresh} done=${body.done} nextCursor=${body.nextCursor} (totals: embedded ${totalEmbedded}, retries ${totalRetries})`);
  if (body.done) {
    sweeps++;
    if (sweepEmbedded === 0) break;
    sweepEmbedded = 0;
    cursor = null;
    continue;
  }
  cursor = body.nextCursor;
  await sleep(500);
}
console.log(JSON.stringify({ totalEmbedded, totalConsidered, pages, sweeps, totalRetries, gaveUp, finalPageSize: pageSize }));
if (gaveUp) process.exit(1);
